import Darwin
import Foundation
import Testing
@testable import SwiftDecompilerCore

/// A W register is the low word of its X register, and a 32-bit flag setter,
/// select or shift works on that word. The tracer read W operands as the
/// whole 64-bit value, took the carry of `cmn`/`tst` from a comparison
/// against zero, left `csinc`/`csinv`/`csneg` arms unfolded and unmasked, and
/// shifted a 32-bit `asr` operand as a positive 64-bit number. Run natively,
/// 367 of 1,061 such constant probes rendered a wrong return value.
/// widthflags.s (generated by widthflags.py) holds 1,174 of them. Each is
/// called natively, and the tracer's exit value must equal the native
/// result or decline.
@Test func thirtyTwoBitFlagsAndSelectsAgreeWithNativeIfPresent() async throws {
    let path = "Fixtures/Sample/libWidthFlagProbes.dylib"
    guard FileManager.default.fileExists(atPath: path) else { return }
    let library = try #require(dlopen(path, RTLD_NOW | RTLD_LOCAL))
    defer { dlclose(library) }
    let functions = try await withStableDependencies {
        try await Disassembler(preset: .default).disassemble(path: path, functionFilter: "wf_")
    }
    try #require(functions.count == 1174)
    var wrong: [String] = []
    var declined = 0
    for function in functions {
        let symbol = function.symbol.hasPrefix("_") ? String(function.symbol.dropFirst()) : function.symbol
        let pointer = try #require(dlsym(library, symbol), "\(symbol)")
        let native = unsafeBitCast(pointer, to: (@convention(c) () -> UInt64).self)()
        let ret = try #require(function.instructions.last)
        switch ValueTracer().analyze(function, entry: nil).exitValues[ret.address] {
        case .immediate(let value)?:
            if value != native { wrong.append("\(symbol): \(String(value, radix: 16)) != native \(String(native, radix: 16))") }
        default:
            declined += 1
        }
    }
    #expect(wrong.isEmpty, "\(wrong.count) wrong:\n\(wrong.prefix(12).joined(separator: "\n"))")
    #expect(declined * 50 < functions.count, "\(declined) of \(functions.count) declined")
}
